        "Tewahedo — Athanasius of Alexandria",
        "Athanasius of Alexandria (350).",
        '<aside class="note-comm-ethiopian"><strong>Athanasius of Alexandria</strong> <em>Orationes contra Arianos II.13</em> <small>(c. 350 AD)</small><p>&#x27;I am Alpha and Omega, the beginning and the ending, saith the Lord, which is, and which was, and which is to come, the Almighty&#x27; — Athanasius marks egō eimi to alpha kai to ō (I-AM the alpha and the omega) as the Apocalyptic-Christ&#x27;s self-predication of divine-comprehension. The alpha-and-omega names the all-encompassing-divine-priority-and-finality (no creature could rightly predicate this of itself). The ho ōn kai ho ēn kai ho erchomenos (the-One-being, the-One-was, the-One-coming) is the Apocalyptic-expansion of the LXX-Ex 3:14 ho ōn — the incarnate-Christ taking-up the burning-bush-self-naming and extending it across the eternal-time-axis. The ho pantokratōr (the-Almighty) is the LXX-translation of Hebrew-El-Shaddai, the highest divine-power-predication. The Tewahedo Apocalyptic-iconology (the Christ-Pantocrator iconography of every Tewahedo-church dome) cites Rev 1:8 as the canonical-self-predication.</p></aside>',
