        "",
        "comm-ethiopian",
        "Tewahedo — Athanasius of Alexandria",
        "Athanasius of Alexandria (350).",
        '<aside class="note-comm-ethiopian"><strong>Athanasius of Alexandria</strong> <em>De Incarnatione Verbi §17</em> <small>(c. 350 AD)</small><p>&#x27;I am he that liveth, and was dead; and, behold, I am alive for evermore, Amen; and have the keys of hell and of death&#x27; — Athanasius marks egō eimi ho zōn, kai egenomēn nekros, kai idou zōn eimi eis tous aiōnas (I-AM the-living-one, and I-became dead, and behold I-AM living unto the ages) as the APOCALYPTIC PASCHAL-IDENTITY-OATH of the risen-Christ. The egō eimi self-predicate identifies the speaker with the Exodus 3:14 divine-Name; the egenomēn nekros (I-BECAME dead) names the assumed-flesh&#x27;s-genuine-death — the Word becomes-dead via-the-flesh, the divine-impassibility preserved by-becoming-dead-in-the-flesh-only; the zōn eimi eis tous aiōnas names the resurrection-as-eternal-state. The &#x27;keys of Hades and of Death&#x27; name the Word&#x27;s-Paschal-cosmic-victory-authority. Tewahedo Eastern Easter Trisagion-paschal-chant cites Rev 1:18 as the resurrection-Paschal-acclamation.</p></aside>',
        "Athanasius of Alexandria, De Incarnatione Verbi (On the Incarnation), in Select Writings and Letters of Athanasius, Nicene and Post-Nicene Fathers (NPNF), Series 2, Vol. 4, ed. Archibald Robertson (Oxford / T&T Clark, 1892). PD. Greek text in Migne PG 25 (1857).",
